/**
 * Recipe data for the Recipes components (awflow/Agentic-Flow#1342). src/data/recipes.json is
 * generated by `bun run recipes:build` from the recipe pages' frontmatter and their .awf files.
 */
import RECIPES from '../../data/recipes.json';
import type { T, UIKey } from '../../i18n/ui';

export type RecipeLevel = 'beginner' | 'intermediate' | 'advanced';
export type RecipeSetup = 'none' | 'connection' | 'on-device';

export interface RecipeNode {
	/** Node id inside the .awf. */
	id: string;
	/** Name the workflow gives the step. */
	label: string;
	registryId: string;
	/** Node type, as the node reference names it. */
	type: string;
	family: string;
	attachment: boolean;
	docLink: string | null;
}

export interface Recipe {
	slug: string;
	href: string;
	title: string;
	description: string;
	goal: string;
	level: RecipeLevel;
	minutes: number;
	setup: RecipeSetup;
	apps: string[];
	/** Registry ids of the nodes the workflow uses. */
	nodes: string[];
	awf: string;
	marketplaceId: string | null;
	graph: RecipeNode[];
	needs: { label: string; href?: string }[];
	touches: { capabilities: string[]; domains: string[]; dynamic: boolean; apps: string[]; models: string[] };
}

/**
 * Goal chips, in the order the index shows them. A recipe's `goal` must be one of these `id`s
 * (the ids are also the `?goal=` URL values, so they stay English); `labelKey` is the dictionary key
 * of the label shown to the reader.
 */
export const GOALS = [
	{ id: 'Research & reading', labelKey: 'recipe.goal.research' },
	{ id: 'Capture to my apps', labelKey: 'recipe.goal.capture' },
	{ id: 'Monitor pages', labelKey: 'recipe.goal.monitor' },
	{ id: 'Fill forms & click', labelKey: 'recipe.goal.forms' },
	{ id: 'Extract data', labelKey: 'recipe.goal.extract' },
	{ id: 'Write with AI', labelKey: 'recipe.goal.write' },
	{ id: 'Chat with my knowledge', labelKey: 'recipe.goal.chat' },
] as const satisfies readonly { id: string; labelKey: UIKey }[];

/** Label of a goal id, in the reader's language. */
export function goalLabel(id: string, t: T): string {
	const goal = GOALS.find((g) => g.id === id);
	return goal ? t(goal.labelKey) : id;
}

const goalRank = (g: string) => {
	const i = GOALS.findIndex((x) => x.id === g);
	if (i < 0) throw new Error(`Recipe goal "${g}" is not one of: ${GOALS.map((x) => x.id).join(', ')}.`);
	return i;
};

/** All recipes, grouped in goal order (then by level and time). */
export const recipes = [...(RECIPES as Recipe[])].sort(
	(a, b) => goalRank(a.goal) - goalRank(b.goal) || a.minutes - b.minutes,
);

/** Levels, easiest first. */
export const LEVELS: readonly RecipeLevel[] = ['beginner', 'intermediate', 'advanced'];

export const levelLabel = (level: RecipeLevel, t: T): string => t(`recipe.level.${level}`);

export const SETUP: Record<RecipeSetup, { labelKey: UIKey; variant: string }> = {
	none: { labelKey: 'recipe.setup.none', variant: 'no-setup' },
	connection: { labelKey: 'recipe.setup.connection', variant: 'connections' },
	'on-device': { labelKey: 'recipe.setup.onDevice', variant: 'on-device' },
};

export const MARKETPLACE_URL = 'https://app.awflow.io/#/app/marketplace';

export function marketplaceHref(r: Pick<Recipe, 'marketplaceId'>): string | null {
	return r.marketplaceId ? `${MARKETPLACE_URL}/${encodeURIComponent(r.marketplaceId)}` : null;
}

/** Throws at build time when a page names a recipe that recipes.json does not have. */
export function getRecipe(slug: string): Recipe {
	const r = recipes.find((x) => x.slug === slug);
	if (!r) throw new Error(`Recipe "${slug}" is not in src/data/recipes.json. Run \`bun run recipes:build\`.`);
	return r;
}
